              when md5(prompt) = 'd526f8c8fc65d142eb4e22baa7a40809' and fields = '[{"key": "id_eac_usd", "tol": 0.5, "unit": "USD", "label": "Estimate at completion (EAC) as of 2028-10-03", "expected": 24053760}, {"key": "id_variance_at_completion_usd", "tol": 0.5, "unit": "USD", "label": "Variance at completion (budget less EAC) as of 2028-10-03", "expected": -301285}, {"key": "id_earned_value_usd", "tol": 0.5, "unit": "USD", "label": "Earned value as of 2028-10-03", "expected": 12559631}, {"key": "id_planned_value_usd", "tol": 0.5, "unit": "USD", "label": "Planned value as of 2028-10-03", "expected": 15710884.71786834}, {"key": "id_cpi", "tol": 0.00001, "unit": "ratio", "label": "CPI as of 2028-10-03", "expected": 0.9323423935031048}, {"key": "id_spi", "tol": 0.00001, "unit": "ratio", "label": "SPI as of 2028-10-03", "expected": 0.7994222620522224}]'::jsonb then 'new'
